// spec: specs/admin-mobile.md (1.1) · кейс: .qa/tests/admin-mobile/ADMIN-MOB-01.md
// seed: tests/seed.admin.spec.ts · ПРОД: только просмотр. Не-GET блокируются, кроме чтения прав rpc/is_admin.
// Урок L-20261110-1: проверяется только сам симптом (вход → панель, нет прокрутки вбок).
import { test, expect } from '@playwright/test';
import { dismissPopups } from '../html-rtl-dir/rtl-dir.helpers';

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const READ_ONLY_RPC = /\/rest\/v1\/rpc\/is_admin$/;

test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test('меню → «מסוף ניהול»: панель по ширине экрана, без белого экрана и прокрутки вбок #6dd27f @mobile @prod-safe', async ({ page }) => {
  await page.route('**/*', (route) => {
    const r = route.request();
    if (SAFE_METHODS.includes(r.method()) || READ_ONLY_RPC.test(r.url().split('?')[0])) return route.fallback();
    return route.abort('blockedbyclient');
  });
  await dismissPopups(page);

  await page.goto('/');
  const menuButton = page.getByRole('banner').getByRole('button', { name: 'תפריט', exact: true });
  await expect(menuButton, 'кнопка ☰ «תפריט»').toBeVisible({ timeout: 20_000 });
  await menuButton.click();
  const menu = page.getByRole('dialog');
  await expect(menu, 'меню открыто').toBeVisible();
  await menu.getByText('מסוף ניהול', { exact: true }).click();

  await page.waitForURL(/\/admin/);
  // «אין הרשאה» может мигнуть — ждём заголовок панели.
  await expect(page.getByRole('heading', { name: 'ניהול - פאנל מנהל' }), 'панель видна, не белый экран').toBeVisible({ timeout: 15_000 });

  const m = await page.evaluate(() => ({
    scrollWidth: document.documentElement.scrollWidth,
    innerWidth: window.innerWidth,
    scrollX: window.scrollX,
  }));
  expect(m.scrollWidth, `ширина страницы ${m.scrollWidth} ≤ ширины экрана ${m.innerWidth}`).toBeLessThanOrEqual(m.innerWidth);
  expect(m.scrollX, 'страница не сдвинута вбок').toBe(0);
});
